r"""GCSE Biology drills (5 questions for each of the 12 skills) and two practice papers (24 questions each).
Original questions written by the Notenix team. Run from this folder: python build.py"""
import sys
from pathlib import Path

sys.path.insert(0, str(Path(__file__).resolve().parent.parent))
from _exam import q, module, save_form, save_drills  # noqa: E402

CO, IB, CI, EG = "Cells and organisation", "Infection and bioenergetics", "Control and inheritance", "Ecology"
CELL, DIV, ORG, HEART = "Cell structure and transport", "Cell division", "Organisation and digestion", "Heart, blood and circulation"
INF, PHOTO, RESP = "Infection and response", "Photosynthesis", "Respiration"
HOME, NERVE, GENE, EVO = "Homeostasis and hormones", "Nervous system", "Inheritance and genetics", "Variation and evolution"
ECO = "Ecology"


def near(x, y, tol=1e-6):
    return abs(x - y) < tol


# ───────────────────────────────────────────────────────────────── drills
D = {}

D[CELL] = ("Animal, plant and bacterial cells, microscopy and magnification, diffusion, osmosis and active transport.", [
    q(CO, CELL, 1, "Which part of a cell contains the genetic material and controls the cell's activities?",
      ["Cell membrane", "Nucleus", "Cytoplasm", "Cell wall"], "B",
      "The nucleus contains the chromosomes, which carry the genetic material. It controls what the cell does. The cell membrane controls what enters and leaves the cell."),
    q(CO, CELL, 2, "Bacterial cells are prokaryotic. Which statement about them is correct?",
      ["They contain mitochondria", "They are larger than most animal cells", "Their DNA is not enclosed in a nucleus", "Their cell wall is made of cellulose"], "C",
      "In prokaryotic cells the genetic material is a single loop of DNA in the cytoplasm, often with small rings called plasmids. They have no nucleus or mitochondria, are much smaller than animal cells, and their cell wall is not made of cellulose."),
    q(CO, CELL, 2, "Root hair cells take in mineral ions from the soil, where the ions are less concentrated than inside the cell. Which process is this?",
      ["Active transport", "Diffusion", "Osmosis", "Transpiration"], "A",
      "Moving substances from a more dilute solution to a more concentrated one is against the concentration gradient. This needs energy from respiration and is called active transport."),
    q(CO, CELL, 2, "A cell is 0.02 mm long. In a drawing of the cell it is 4 mm long. What is the magnification of the drawing?",
      [r"$\times 0.005$", r"$\times 20$", r"$\times 80$", r"$\times 200$"], "D",
      r"Magnification $= \dfrac{\text{size of image}}{\text{size of real object}} = \dfrac{4}{0.02} = 200$. Both lengths must be in the same unit before dividing.",
      check=lambda: near(4 / 0.02, 200)),
    q(CO, CELL, 3, r"A cube of side 1 cm has a surface area of $6\ \text{cm}^2$ and a volume of $1\ \text{cm}^3$. A cube of side 2 cm has a surface area of $24\ \text{cm}^2$ and a volume of $8\ \text{cm}^3$. Which statement is correct?",
      ["The larger cube has the larger surface area to volume ratio", "The smaller cube's surface area to volume ratio is twice that of the larger cube",
       "Both cubes have the same surface area to volume ratio", "The smaller cube's surface area to volume ratio is half that of the larger cube"], "B",
      "The smaller cube's ratio is 6 : 1 and the larger cube's is 24 : 8, which is 3 : 1. So the smaller cube's ratio is twice as large. This is why small organisms can rely on diffusion across their surface, while large ones need exchange surfaces and transport systems.",
      check=lambda: 6 / 1 == 2 * (24 / 8)),
])

D[DIV] = ("Chromosomes, the cell cycle and mitosis, stem cells, meristems and bacterial growth.", [
    q(CO, DIV, 1, "What name is given to undifferentiated cells that can develop into many different types of cell?",
      ["Stem cells", "Gametes", "Red blood cells", "Guard cells"], "A",
      "Stem cells are undifferentiated. They can divide and then differentiate into specialised cells. They are found in embryos, in adult bone marrow and in plant meristems."),
    q(CO, DIV, 2, "Before a cell divides by mitosis, what happens to its DNA?",
      ["It is broken down", "It is halved", "It is replicated, so there are two copies of each chromosome", "It leaves the nucleus"], "C",
      "During the cell cycle the cell grows, makes more organelles and replicates its DNA. Each chromosome is copied so that each new cell receives a full set."),
    q(CO, DIV, 2, "Where are meristem cells found in a plant?",
      ["In the xylem vessels", "At the tips of the roots and shoots", "In the guard cells", "In the waxy cuticle"], "B",
      "Meristem tissue at the tips of roots and shoots contains stem cells. These can differentiate into any type of plant cell throughout the plant's life."),
    q(CO, DIV, 2, "Mitosis is NOT used for which of these?",
      ["Growth of an organism", "Repairing damaged tissue", "Asexual reproduction", "Producing sperm and egg cells"], "D",
      "Mitosis makes genetically identical cells for growth, repair and asexual reproduction. Gametes such as sperm and egg cells are made by meiosis, which halves the number of chromosomes."),
    q(CO, DIV, 3, "A bacterium divides once every 20 minutes. Starting with a single bacterium, how many bacteria will there be after 2 hours, if none die?",
      ["6", "12", "64", "32"], "C",
      r"2 hours is 120 minutes, which is $120 \div 20 = 6$ divisions. The number doubles each time, so there are $2^6 = 64$ bacteria.",
      check=lambda: 2 ** (120 // 20) == 64),
])

D[ORG] = ("Levels of organisation, the digestive system, enzymes, food tests and plant tissues.", [
    q(CO, ORG, 1, "Which list shows the levels of organisation from smallest to largest?",
      ["Tissue, cell, organ, organ system", "Cell, organ, tissue, organ system", "Cell, tissue, organ, organ system", "Organ system, organ, tissue, cell"], "C",
      "Similar cells form a tissue, several tissues form an organ, and organs working together form an organ system."),
    q(CO, ORG, 2, "Which reagent is used to test a food for protein?",
      ["Iodine solution", "Benedict's solution", "Ethanol", "Biuret reagent"], "D",
      "Biuret reagent turns from blue to purple (lilac) if protein is present. Iodine tests for starch, Benedict's for sugars, and ethanol for lipids."),
    q(CO, ORG, 2, "What does bile do in digestion?",
      ["It digests proteins into amino acids", "It neutralises stomach acid and emulsifies fats", "It absorbs water from food", "It breaks down starch into sugars"], "B",
      "Bile is made in the liver and stored in the gall bladder. It is alkaline, so it neutralises stomach acid, and it emulsifies fats into small droplets, giving lipase a larger surface area to work on."),
    q(CO, ORG, 2, "Why does an enzyme stop working at a high temperature?",
      ["The shape of its active site changes, so the substrate no longer fits", "It runs out of energy", "It is killed by the heat", "It turns into the substrate"], "A",
      "High temperatures break bonds that hold the enzyme in shape. The active site changes shape and the substrate no longer fits, so the enzyme is denatured. Enzymes are proteins, not living things, so they are not killed."),
    q(CO, ORG, 3, "Which change in conditions would increase the rate of transpiration from a plant?",
      ["A lower temperature", "Higher humidity", "More air movement", "Lower light intensity"], "C",
      "Moving air carries water vapour away from the leaf, keeping a steep concentration gradient, so water evaporates and diffuses out faster. Lower temperature, higher humidity and dimmer light all reduce the rate."),
])

D[HEART] = ("The heart, blood vessels, components of blood and coronary heart disease.", [
    q(CO, HEART, 1, "Which component of the blood carries oxygen?",
      ["Plasma", "Platelets", "White blood cells", "Red blood cells"], "D",
      "Red blood cells contain haemoglobin, which binds to oxygen. They have no nucleus and a biconcave shape, giving more room and a larger surface area for oxygen."),
    q(CO, HEART, 2, "Why do arteries have thick, muscular and elastic walls?",
      ["To withstand blood at high pressure", "To let substances diffuse through them", "Because they contain valves", "Because they carry blood back to the heart"], "A",
      "Arteries carry blood away from the heart at high pressure. Thick muscle and elastic fibres let them withstand and smooth out this pressure. Veins carry blood back to the heart and have valves."),
    q(CO, HEART, 2, "Which chamber of the heart pumps blood out to the rest of the body?",
      ["Right atrium", "Left ventricle", "Right ventricle", "Left atrium"], "B",
      "The left ventricle pumps oxygenated blood into the aorta and around the body. It has the thickest wall because it must pump blood the furthest. The right ventricle pumps blood to the lungs."),
    q(CO, HEART, 2, "Why is the human circulatory system described as a double circulatory system?",
      ["There are two hearts", "Blood flows in both directions in each vessel",
       "Blood passes through the heart twice for each complete circuit of the body", "Each organ has two arteries"], "C",
      "One circuit takes blood from the heart to the lungs and back, and the other takes it from the heart to the rest of the body and back. So blood passes through the heart twice in each full circuit."),
    q(CO, HEART, 3, "In coronary heart disease, layers of fatty material build up inside the coronary arteries. Why is this harmful?",
      ["It makes the heart beat faster", "It makes the heart wall thicker", "It stops the heart valves from closing",
       "It reduces blood flow to the heart muscle, so the muscle gets less oxygen"], "D",
      "The coronary arteries supply the heart muscle itself with oxygenated blood. If they narrow, less oxygen reaches the muscle, which can cause chest pain or a heart attack. Stents or statins can be used to treat it."),
])

D[INF] = ("Pathogens and the diseases they cause, the body's defences, vaccination, antibiotics and drug trials.", [
    q(IB, INF, 1, "What type of pathogen causes malaria?", ["Virus", "Bacterium", "Protist", "Fungus"], "C",
      "Malaria is caused by a protist. It is spread by mosquitoes, which act as vectors. Preventing mosquito bites, for example with nets, reduces the spread."),
    q(IB, INF, 2, "How do some white blood cells help to defend the body against pathogens?",
      ["They produce antibodies", "They carry oxygen to the pathogens", "They form a clot over the pathogen", "They release hormones that kill viruses"], "A",
      "White blood cells defend the body by engulfing pathogens (phagocytosis), producing antibodies, and producing antitoxins. Clotting is the job of platelets."),
    q(IB, INF, 2, "How does a vaccine protect a person from a disease?",
      ["It contains antibiotics that kill the pathogen", "It contains a dead or inactive form of the pathogen, so white blood cells make antibodies and memory cells",
       "It contains antibodies taken from another person", "It destroys viruses inside the body's cells"], "B",
      "The vaccine stimulates white blood cells to produce antibodies. Memory cells remain, so if the real pathogen enters later, antibodies are made quickly and the person does not become ill."),
    q(IB, INF, 2, "Which of these diseases is caused by a bacterium?",
      ["Measles", "Salmonella food poisoning", "Rose black spot", "HIV"], "B",
      "Salmonella food poisoning is caused by bacteria. Measles and HIV are caused by viruses, and rose black spot is caused by a fungus."),
    q(IB, INF, 3, "In a double-blind trial of a new drug, who knows which patients are receiving the drug and which are receiving a placebo?",
      ["Only the doctors", "Only the patients", "Both the doctors and the patients", "Neither the doctors nor the patients"], "D",
      "In a double-blind trial neither the doctors nor the patients know who has the drug and who has the placebo until the end. This stops expectations from affecting the results."),
])

D[PHOTO] = ("The photosynthesis reaction, limiting factors, the inverse square law and how plants use glucose.", [
    q(IB, PHOTO, 1, "Which gas do plants take in from the air for photosynthesis?", ["Oxygen", "Carbon dioxide", "Nitrogen", "Hydrogen"], "B",
      "Photosynthesis uses carbon dioxide and water to make glucose and oxygen. Carbon dioxide enters the leaf through the stomata."),
    q(IB, PHOTO, 2, "Why is photosynthesis described as an endothermic reaction?",
      ["Energy is transferred from the environment to the chloroplasts by light", "It gives out heat", "It only happens at night", "It uses up oxygen"], "A",
      "An endothermic reaction takes in energy from the surroundings. In photosynthesis the energy is transferred by light and absorbed by chlorophyll in the chloroplasts."),
    q(IB, PHOTO, 2, "On a warm, bright day the rate of photosynthesis of a plant stops increasing, even when the light gets brighter. Which factor is most likely to be limiting the rate?",
      ["Light intensity", "Oxygen concentration", "Carbon dioxide concentration", "The length of the day"], "C",
      "Light cannot be limiting, because making it brighter has no effect, and the day is already warm. Carbon dioxide concentration is the most likely limiting factor. Oxygen is a product, not a reactant."),
    q(IB, PHOTO, 2, "Plants turn some of the glucose they make into starch for storage. Why is starch useful for storage?",
      ["It dissolves easily in water", "It is used directly to make proteins", "It releases oxygen while it is stored",
       "It is insoluble, so it does not draw water into cells by osmosis"], "D",
      "Starch is insoluble. Storing lots of soluble glucose would make cells draw in water by osmosis. Plants also use glucose for respiration, cellulose for cell walls, and with nitrate ions to make proteins."),
    q(IB, PHOTO, 3, "A lamp is moved from 10 cm to 20 cm away from a plant. According to the inverse square law, what happens to the light intensity at the plant?",
      ["It halves", "It doubles", "It falls to a quarter", "It stays the same"], "C",
      r"Light intensity is proportional to $\dfrac{1}{d^2}$. Doubling the distance gives $\left(\dfrac{1}{2}\right)^2 = \dfrac{1}{4}$ of the intensity.",
      check=lambda: (10 / 20) ** 2 == 0.25),
])

D[RESP] = ("Aerobic and anaerobic respiration, fermentation, exercise, oxygen debt and metabolism.", [
    q(IB, RESP, 1, "Where in a cell does most aerobic respiration take place?", ["Nucleus", "Ribosomes", "Mitochondria", "Cell membrane"], "C",
      "Aerobic respiration takes place mainly in the mitochondria. Cells that need a lot of energy, such as muscle and sperm cells, have many mitochondria."),
    q(IB, RESP, 2, "Which word equation shows aerobic respiration?",
      ["glucose + oxygen → carbon dioxide + water", "glucose → lactic acid", "glucose → ethanol + carbon dioxide", "carbon dioxide + water → glucose + oxygen"], "A",
      "Aerobic respiration uses oxygen to break down glucose completely, producing carbon dioxide and water and transferring energy. The last equation is photosynthesis."),
    q(IB, RESP, 2, "What are the products of anaerobic respiration in yeast cells?",
      ["Lactic acid", "Ethanol and carbon dioxide", "Oxygen and water", "Carbon dioxide and water only"], "B",
      "Anaerobic respiration in yeast is called fermentation. It produces ethanol and carbon dioxide, which is why yeast is used in brewing and bread-making. Muscle cells make lactic acid instead."),
    q(IB, RESP, 3, "Why does anaerobic respiration transfer much less energy per molecule of glucose than aerobic respiration?",
      ["It happens more slowly", "The oxidation of glucose is incomplete", "It uses more glucose", "It happens outside cells"], "B",
      "Without oxygen, glucose is only partly broken down, so much of its energy stays in the products such as lactic acid. Aerobic respiration oxidises glucose completely."),
    q(IB, RESP, 3, "After hard exercise, a person keeps breathing deeply and quickly for some time. Why?",
      ["To cool the body down", "To remove excess glucose from the blood", "To make more lactic acid",
       "To repay the oxygen debt, supplying oxygen to break down lactic acid"], "D",
      "Lactic acid builds up during anaerobic respiration. The extra oxygen needed to deal with it is the oxygen debt. Blood carries the lactic acid to the liver, where it is converted back into glucose."),
])

D[HOME] = ("Homeostasis, the endocrine system, blood glucose and diabetes, reproductive hormones and plant hormones.", [
    q(CI, HOME, 1, "Which gland is often called the 'master gland' because it releases hormones that control other glands?",
      ["Pituitary gland", "Adrenal gland", "Pancreas", "Thyroid gland"], "A",
      "The pituitary gland in the brain releases several hormones, such as FSH, LH and TSH, that act on other glands and cause them to release their own hormones."),
    q(CI, HOME, 2, "What is the cause of Type 1 diabetes?",
      ["Body cells stop responding to insulin", "The liver makes too much glucagon", "The pancreas produces little or no insulin", "Eating too much sugar"], "C",
      "In Type 1 diabetes the pancreas produces too little insulin, so it is treated with insulin injections. In Type 2 diabetes the body's cells no longer respond properly to insulin."),
    q(CI, HOME, 2, "Which of these is an effect of the hormone adrenaline?",
      ["It decreases heart rate", "It lowers blood glucose concentration", "It slows breathing", "It increases heart rate"], "D",
      "Adrenaline is released by the adrenal glands in times of fear or stress. It increases heart rate, boosting the delivery of oxygen and glucose to the brain and muscles and preparing the body for 'fight or flight'."),
    q(CI, HOME, 2, "In the menstrual cycle, which hormone causes an egg to mature in the ovary?", ["FSH", "Oestrogen", "LH", "Progesterone"], "A",
      "FSH (follicle stimulating hormone) from the pituitary gland causes an egg to mature. LH triggers ovulation, and oestrogen and progesterone build up and maintain the lining of the uterus."),
    q(CI, HOME, 3, "A person's blood glucose concentration falls too low. How does the body respond?",
      ["The pancreas releases insulin, so glucose moves into cells", "The pancreas releases glucagon, so the liver converts glycogen into glucose",
       "The liver stores more glycogen", "The kidneys release glucose into the urine"], "B",
      "When blood glucose is too low, the pancreas releases glucagon. This causes the liver to convert stored glycogen into glucose, which is released into the blood. This is an example of negative feedback."),
])

D[NERVE] = ("Neurones and reflex arcs, synapses, the brain and the eye.", [
    q(CI, NERVE, 1, "What does a sensory neurone do?",
      ["Carries impulses from the central nervous system to muscles", "Connects neurones within the brain only",
       "Carries impulses from receptors to the central nervous system", "Produces hormones"], "C",
      "Sensory neurones carry electrical impulses from receptors to the central nervous system. Motor neurones carry impulses from the central nervous system to effectors."),
    q(CI, NERVE, 2, "What is a synapse?",
      ["A type of receptor in the skin", "The gap between two neurones, which is crossed by chemicals",
       "The part of the brain that controls balance", "A muscle that responds to impulses"], "B",
      "A synapse is a junction between two neurones. The impulse cannot jump the gap, so a chemical is released that diffuses across and starts an impulse in the next neurone."),
    q(CI, NERVE, 2, "Why are reflex actions important?",
      ["They are slow and carefully thought about", "They are controlled by hormones", "They only happen during sleep",
       "They are rapid and automatic, which helps to protect the body"], "D",
      "Reflexes do not involve the conscious part of the brain, so they are very fast. Examples include pulling your hand away from something hot and the pupil narrowing in bright light."),
    q(CI, NERVE, 2, "Which part of the eye controls how much light enters it?", ["Iris", "Retina", "Lens", "Cornea"], "A",
      "The iris contains muscles that change the size of the pupil. In bright light the pupil becomes smaller, letting less light in. The retina contains the light receptors."),
    q(CI, NERVE, 3, "Which part of the brain controls unconscious activities such as heart rate and breathing?",
      ["Cerebral cortex", "Cerebellum", "Medulla", "Pituitary gland"], "C",
      "The medulla controls unconscious activities such as heartbeat and breathing. The cerebral cortex is involved in memory, language and consciousness, and the cerebellum coordinates muscle activity and balance."),
])

D[GENE] = ("DNA and genes, meiosis, sexual and asexual reproduction, alleles and genetic crosses.", [
    q(CI, GENE, 1, "What is a gene?",
      ["A type of cell", "A small section of DNA that codes for a particular protein", "All of an organism's genetic material", "A pair of chromosomes"], "B",
      "A gene is a small section of DNA on a chromosome. It codes for a particular sequence of amino acids, which makes a specific protein. All of an organism's genetic material is its genome."),
    q(CI, GENE, 2, "What does it mean if a person is homozygous for a gene?",
      ["They have two different alleles of the gene", "They have only one copy of each chromosome",
       "They have a mutation in the gene", "They have two identical alleles of the gene"], "D",
      "Homozygous means having two copies of the same allele, for example BB or bb. Heterozygous means having two different alleles, such as Bb."),
    q(CI, GENE, 2, "A human body cell has 46 chromosomes. How many chromosomes does a human egg cell have?", ["46", "23", "92", "22"], "B",
      "Gametes are made by meiosis, which halves the number of chromosomes. An egg cell has 23, so when it is fertilised by a sperm with 23, the embryo has the full 46.",
      check=lambda: 46 // 2 == 23),
    q(CI, GENE, 2, "Which statement about sexual reproduction is correct?",
      ["It involves the fusion of male and female gametes, producing variation", "It produces offspring that are clones of the parent",
       "It needs only one parent", "Its gametes are made by mitosis"], "A",
      "Sexual reproduction joins genetic information from two parents when gametes fuse. The offspring are genetically different, which produces variation. Asexual reproduction needs one parent and produces clones."),
    q(CI, GENE, 3, "In pea plants, the allele for purple flowers (P) is dominant to the allele for white flowers (p). A plant with genotype Pp is crossed with a plant with genotype pp. What percentage of the offspring are expected to have white flowers?",
      ["0%", "25%", "75%", "50%"], "D",
      "The Pp parent gives P or p, and the pp parent always gives p. The offspring are Pp and pp in equal numbers. Only pp plants are white, so 50% are expected to be white.",
      check=lambda: [a + b for a in "Pp" for b in "pp"].count("pp") / 4 == 0.5),
])

D[EVO] = ("Variation, mutation, natural selection, selective breeding, genetic engineering, fossils and classification.", [
    q(CI, EVO, 1, "Who proposed the theory of evolution by natural selection?", ["Gregor Mendel", "Charles Darwin", "Louis Pasteur", "Alexander Fleming"], "B",
      "Charles Darwin published the theory of evolution by natural selection in 1859, based on his observations and experiments. Gregor Mendel carried out early work on inheritance using pea plants."),
    q(CI, EVO, 2, "Which of these characteristics is caused only by the environment?",
      ["Blood group", "Eye colour", "A scar from an injury", "Natural hair colour"], "C",
      "A scar results from something that happened to the person, so it is environmental. Blood group, eye colour and natural hair colour are inherited from the parents."),
    q(CI, EVO, 2, "What is selective breeding?",
      ["Animals choosing their own mates in the wild", "Changing an organism's genes using enzymes", "The survival of the best adapted organisms in nature",
       "Humans choosing organisms with desired characteristics and breeding them together"], "D",
      "In selective breeding humans choose parents with a useful characteristic, breed them, and repeat over many generations. Changing genes with enzymes is genetic engineering, and survival of the best adapted is natural selection."),
    q(CI, EVO, 2, "Why is the fossil record incomplete?",
      ["Many early organisms were soft-bodied and left few traces", "Fossils have only formed in the last thousand years",
       "Only animals with backbones lived in the past", "Every fossil that formed has been found"], "A",
      "Soft-bodied organisms rarely formed fossils, and many fossils have been destroyed by geological activity or have not yet been found. This is why scientists cannot be certain how life began."),
    q(CI, EVO, 3, "Bacteria can be genetically engineered to make human insulin. What is used as a vector to carry the human insulin gene into a bacterial cell?",
      ["A ribosome", "A red blood cell", "A chloroplast", "A plasmid"], "D",
      "The gene is cut out using enzymes and inserted into a plasmid, a small ring of DNA. The plasmid carries the gene into the bacterium, which then makes insulin as it grows and divides."),
])

D[ECO] = ("Food chains, biotic and abiotic factors, cycles of materials, biomass transfer and biodiversity.", [
    q(EG, ECO, 1, "What is a producer in a food chain?",
      ["An animal that eats plants", "An organism that makes its own food, usually by photosynthesis",
       "An animal that eats other animals", "An organism that breaks down dead material"], "B",
      "Producers, such as green plants and algae, make glucose by photosynthesis. They are always at the start of a food chain."),
    q(EG, ECO, 2, "Which of these is an abiotic factor?", ["Temperature", "Predation", "A new pathogen", "Competition for food"], "A",
      "Abiotic factors are non-living, such as temperature, light intensity, moisture, soil pH and wind. Predation, pathogens and competition are biotic, because they involve living things."),
    q(EG, ECO, 2, "In the carbon cycle, how do decomposers return carbon to the atmosphere?",
      ["By photosynthesis", "By combustion", "By respiring as they break down dead material, releasing carbon dioxide", "By absorbing carbon dioxide"], "C",
      "Decomposers such as bacteria and fungi feed on dead organisms and waste. As they respire, they release carbon dioxide into the air, and mineral ions are returned to the soil."),
    q(EG, ECO, 3, "In a food chain, the producers have a biomass of 10 000 kg and the primary consumers have a biomass of 1000 kg. What is the efficiency of biomass transfer?",
      ["1%", "90%", "0.1%", "10%"], "D",
      r"Efficiency $= \dfrac{\text{biomass transferred to the next level}}{\text{biomass available}} \times 100 = \dfrac{1000}{10\,000} \times 100 = 10\%$.",
      check=lambda: 1000 / 10000 * 100 == 10),
    q(EG, ECO, 2, "In a predator-prey relationship, what usually happens soon after the number of prey increases?",
      ["The number of predators increases", "The number of predators decreases", "The prey stop reproducing", "The predator population stays exactly the same"], "A",
      "More prey means more food for the predators, so more of them survive and breed and their numbers rise. The predator peak comes a little after the prey peak."),
])

save_drills("gcse-biology", D)

# ───────────────────────────────────────────────────────────────── practice paper 1
M1P1 = [
    q(CO, CELL, 1, "Which part of a cell controls which substances enter and leave it?", ["Nucleus", "Cell membrane", "Cell wall", "Ribosome"], "B",
      "The cell membrane controls the passage of substances in and out of the cell. The cell wall, found in plant and bacterial cells, strengthens the cell."),
    q(CO, CELL, 2, "What is diffusion?",
      ["The movement of water only across a membrane", "The movement of particles against a concentration gradient, using energy",
       "The movement of particles from a lower to a higher concentration", "The net movement of particles from a higher to a lower concentration"], "D",
      "Diffusion is the spreading out of particles, giving a net movement from where they are more concentrated to where they are less concentrated. It needs no energy from the cell."),
    q(CO, CELL, 2, "Which part of a cell is the site of protein synthesis?", ["Ribosome", "Mitochondrion", "Permanent vacuole", "Chloroplast"], "A",
      "Proteins are made on ribosomes. Mitochondria are where aerobic respiration happens, and chloroplasts are where photosynthesis happens."),
    q(CO, DIV, 2, "What is the process called by which a cell becomes specialised for a particular job?", ["Mitosis", "Meiosis", "Differentiation", "Diffusion"], "C",
      "Differentiation is when a cell gains the structures it needs to carry out a particular function. Most animal cells differentiate early in development, but many plant cells keep the ability throughout life."),
    q(CO, ORG, 1, "Which organ produces bile?", ["Gall bladder", "Liver", "Stomach", "Pancreas"], "B",
      "Bile is made in the liver. It is stored in the gall bladder and released into the small intestine."),
    q(CO, ORG, 2, "Which reagent is used to test for starch, and what colour shows that starch is present?",
      ["Iodine solution, turning blue-black", "Benedict's solution, turning brick red", "Biuret reagent, turning purple", "Iodine solution, staying orange-brown"], "A",
      "Iodine solution changes from orange-brown to blue-black when starch is present. Benedict's solution is used for sugars and Biuret reagent for proteins."),
    q(CO, ORG, 2, "Which plant tissue transports dissolved sugars around the plant?", ["Xylem", "Epidermis", "Palisade mesophyll", "Phloem"], "D",
      "Phloem carries dissolved sugars from the leaves to the rest of the plant. This is called translocation. Xylem carries water and mineral ions up from the roots."),
    q(CO, HEART, 2, "Why do veins contain valves?",
      ["To make the blood flow faster", "To let oxygen diffuse out of the blood", "To stop blood flowing backwards", "To raise the blood pressure"], "C",
      "Blood in veins is at low pressure, so valves are needed to keep it flowing towards the heart and stop it flowing backwards."),
    q(IB, INF, 1, "Which of these diseases is caused by a virus?", ["Measles", "Malaria", "Gonorrhoea", "Athlete's foot"], "A",
      "Measles is caused by a virus and is spread by droplets from sneezes and coughs. Malaria is caused by a protist, gonorrhoea by a bacterium and athlete's foot by a fungus."),
    q(IB, INF, 2, "Which of these is a non-specific defence of the human body against pathogens?",
      ["Antibodies", "The skin acting as a barrier", "Vaccination", "Antibiotics"], "B",
      "Non-specific defences stop any pathogen getting in. They include the skin, hairs and mucus in the nose, and acid in the stomach. Antibodies are specific to one pathogen."),
    q(IB, PHOTO, 1, "In which part of a plant cell does photosynthesis take place?", ["Nucleus", "Mitochondria", "Chloroplasts", "Cell wall"], "C",
      "Chloroplasts contain chlorophyll, which absorbs the light energy needed for photosynthesis."),
    q(IB, RESP, 2, "Which statement correctly compares aerobic and anaerobic respiration in human muscle?",
      ["Only aerobic respiration produces lactic acid", "Anaerobic respiration transfers more energy per glucose molecule",
       "Aerobic respiration does not need oxygen", "Only anaerobic respiration produces lactic acid"], "D",
      "Anaerobic respiration in muscles produces lactic acid and transfers much less energy. Aerobic respiration needs oxygen and produces carbon dioxide and water."),
]

M1P2 = [
    q(CI, HOME, 1, "What is homeostasis?",
      ["The response of an organism to a stimulus", "The production of hormones by glands",
       "Keeping the body's internal conditions within set limits", "The transport of substances in the blood"], "C",
      "Homeostasis is the regulation of internal conditions, such as body temperature, blood glucose and water levels, to keep them at the best levels for cells and enzymes to work."),
    q(CI, HOME, 2, "How are hormones carried around the body?",
      ["In the blood plasma", "Along neurones as electrical impulses", "Through the digestive system", "In the air in the lungs"], "A",
      "Hormones are chemicals released by glands directly into the bloodstream. They travel in the blood plasma to their target organs, so their effects are slower than nerve impulses."),
    q(CI, HOME, 2, "How does a contraceptive pill containing oestrogen and progesterone prevent pregnancy?",
      ["It kills sperm", "It forms a barrier at the cervix", "It makes the lining of the uterus thicker", "It stops FSH production, so no eggs mature"], "D",
      "The hormones in the pill inhibit the production of FSH, so eggs do not mature and are not released. Spermicides kill sperm, and barrier methods stop sperm reaching the egg."),
    q(CI, NERVE, 1, "What is a change in the environment that an organism can detect called?", ["A response", "A stimulus", "An effector", "A receptor"], "B",
      "A stimulus is a change in the environment, such as light, sound or temperature. Receptors detect stimuli, and effectors bring about the response."),
    q(CI, NERVE, 2, "In the nervous system, what are effectors?",
      ["Muscles or glands that bring about a response", "Cells that detect stimuli", "Neurones in the spinal cord", "Chemicals that cross synapses"], "A",
      "Effectors are muscles, which contract, and glands, which release hormones. They respond to impulses carried by motor neurones."),
    q(CI, GENE, 1, "Which molecule carries the genetic information in cells?", ["Glucose", "Starch", "DNA", "Protein"], "C",
      "Genetic information is carried by DNA, which is found in chromosomes in the nucleus. DNA is a polymer made of two strands twisted into a double helix."),
    q(CI, GENE, 2, "What is a dominant allele?",
      ["An allele that is only expressed when two copies are present", "An allele that is expressed even if only one copy is present",
       "An allele that is found only in males", "An allele that always causes a disorder"], "B",
      "A dominant allele shows its effect when just one copy is present. A recessive allele only shows its effect when two copies are present."),
    q(CI, GENE, 3, "In a species, brown eyes (B) is dominant to blue eyes (b). Two heterozygous parents (Bb) have children. What is the expected ratio of brown-eyed to blue-eyed offspring?",
      ["1 : 1", "1 : 3", "2 : 1", "3 : 1"], "D",
      "The possible offspring are BB, Bb, Bb and bb. Three of the four have at least one B allele and have brown eyes, and one is bb with blue eyes. The ratio is 3 : 1.",
      check=lambda: sum(1 for a in "Bb" for b in "Bb" if "B" in a + b) == 3),
    q(CI, EVO, 2, "What is a change in the DNA sequence of a gene called?", ["Adaptation", "Evolution", "Mutation", "Selection"], "C",
      "A mutation is a change in DNA. Mutations happen all the time. Most have no effect, but occasionally one gives a new characteristic that helps an organism survive."),
    q(CI, EVO, 2, "Which of these could cause a species to become extinct?",
      ["A new disease or predator", "An increase in its food supply", "Less competition for resources", "A mild winter"], "A",
      "Extinction can be caused by new diseases, new predators, new competitors, or changes to the environment that happen faster than the species can adapt."),
    q(EG, ECO, 1, "What do the arrows in a food chain show?",
      ["The direction the animals migrate", "Which organism is the largest", "Which organism lives the longest",
       "The transfer of energy and biomass from one organism to the next"], "D",
      "Each arrow points from the organism being eaten to the organism that eats it. It shows the direction in which biomass and energy are transferred."),
    q(EG, ECO, 2, "Which of these helps to maintain or increase biodiversity?",
      ["Cutting down rainforests", "Breeding programmes for endangered species", "Draining peat bogs", "Using more pesticides"], "B",
      "Breeding programmes protect endangered species. Other helpful measures include protecting habitats, replanting hedgerows and reducing deforestation. The other choices all reduce biodiversity."),
]

